<?php
declare(strict_types=1);
use Sokna\Local\UI\WebAction;
$core=require dirname(__DIR__).'/_app.php';$user=$core->auth()->currentUser();if(!is_array($user))WebAction::json(['success'=>false,'code'=>'unauthenticated','message'=>'نشست پایان یافته است.'],401);
try{if(($_SERVER['REQUEST_METHOD']??'GET')==='GET')WebAction::json(['success'=>true,'snapshot'=>$core->notifications()->snapshot($user)]);$d=WebAction::requireMutation();$a=(string)($d['action']??'');$s=$core->notifications();if($a==='preferences')WebAction::json(['success'=>true,'result'=>$s->savePreferences($d,$user)]);if($a==='register_push')WebAction::json(['success'=>true,'result'=>$s->registerPush(is_array($d['subscription']??null)?$d['subscription']:[],$user)]);if($a==='unregister_push')WebAction::json(['success'=>true,'result'=>$s->unregisterPush((string)($d['endpoint']??''),$user)]);if($a==='mark_read')WebAction::json(['success'=>true,'result'=>$s->markRead((int)($d['id']??0),$user)]);if($a==='compose')WebAction::json(['success'=>true,'result'=>$s->compose($d,$user)]);WebAction::json(['success'=>false,'code'=>'invalid_action','message'=>'عملیات معتبر نیست.'],422);}catch(Throwable $e){if(property_exists($e,'httpStatus'))WebAction::knownFailure($e);error_log('notifications api: '.$e->getMessage());WebAction::json(['success'=>false,'code'=>'internal_error','message'=>'عملیات اعلان انجام نشد.'],500);}
